      {
        id: "mlops-u7-l4-drift-monitoramento-testes",
        title: "Detecção de Data Drift e Concept Drift",
        subtitle: "Monitoramento contínuo · Kolmogorov-Smirnov, PSI, Population Drift e degradação de acurácia",
        theory: "Modelos degradam em produção conforme o mundo muda. Data Drift é a alteração na distribuição das entradas frente ao treino. Concept Drift é a mudança na relação entre features e o alvo. Testes como Kolmogorov-Smirnov e PSI alertam a equipe antes de perdas de acurácia.",
        questions: [
          q("Qual é a diferença entre Data Drift (Covariate Shift) e Concept Drift?", "Data Drift é a mudança na distribuição das features de entrada; Concept Drift é a mudança na relação entre features e o alvo", ["Data Drift afeta apenas imagens e Concept Drift afeta apenas tabelas numéricas","Data Drift ocorre antes do deploy e Concept Drift ocorre apenas no notebook de testes"], "Data drift altera a entrada P(X); concept drift altera a relação condicional P(Y|X)."),
          q("Qual teste estatístico não paramétrico compara se uma feature numérica contínua sofreu alteração de distribuição?", "Teste de Kolmogorov-Smirnov (KS-test)", ["Regressão de Ridge com penalização L2","Matriz de confusão normalizada por coluna"], "O teste KS compara a função de distribuição cumulativa empírica entre duas amostras."),
          q("O que o índice PSI (Population Stability Index) avalia no monitoramento de modelos em produção?", "A magnitude do deslocamento populacional de uma variável ou score entre o baseline de referência e a produção", ["O tempo de latência gasto por pacote TCP na rede do servidor","A quantidade de falhas de hardware nos discos rígidos do cluster"], "PSI é uma métrica consolidada para quantificar estabilidade populacional (valores > 0.2 indicam drift severo)."),
          q("Por que o Concept Drift pode passar despercebido por testes de distribuição nas variáveis de entrada?", "Porque as entradas podem manter suas médias idênticas, mas o comportamento dos usuários (alvo real) mudou", ["Porque o Scikit-Learn oculta erros matemáticos automaticamente","Porque o Concept Drift só afeta variáveis que foram excluídas no treino"], "Se as features mantêm a mesma distribuição mas a verdade de solo mudou, apenas métricas de desempenho revelam o drift."),
          t("Qual teste estatístico de dois dados compara distribuições cumulativas para detecção de drift contínuo?", ["ks_2samp","kolmogorov-smirnov","ks test"], "scipy.stats.ks_2samp executa o teste de Kolmogorov-Smirnov para duas amostras."),
          g("Complete o cálculo do teste de Kolmogorov-Smirnov entre treino e produção:", ["ks_2samp"], "ks_2samp compara a amostra histórica de treino com os dados coletados na produção.", "from scipy.stats import ks_2samp\nstat, p_valor = ____(X_treino[\"idade\"], X_producao[\"idade\"])"),
          o("Ordene o ciclo de detecção e resposta ao drift em produção:", ["Armazenar amostras de payloads de inferência recebidos em produção","Calcular testes estatísticos (KS-test e PSI) comparando produção com o baseline","Disparar alertas operacionais quando as métricas excederem os limiares críticos","Investigar a causa-raiz e acionar o pipeline de retreinamento do modelo"], "Coleta de inferências, comparação estatística com o baseline, alerta e retreinamento."),
          p("Associe o tipo de anomalia de produção ao seu indicador de diagnóstico:", [["Data Drift","Variação estatística significativa na distribuição marginal de P(X)"],["Concept Drift","Degradação da relação preditiva P(Y|X) sem alteração visível em P(X)"],["PSI > 0.25","Deslocamento populacional severo exigindo intervenção e retreino"],["Ground Truth Lag","Atraso temporal entre a inferência e a observação do desfecho real de negócio"]], "Monitorar distribuições e atrasos de feedback evita que modelos degradados operem no escuro.")
        ]
      },
      {
        id: "mlops-u7-l5-retreinamento-e-deploy-estrategias",
        title: "Estratégias de retreinamento e deploy seguro",
        subtitle: "Operação sustentável · Canary deployment, Shadow mode, Blue-Green e gatilhos de retreino",
        theory: "Substituir modelos em produção exige cautela extrema para evitar interrupções de serviço. O deploy em modo Shadow envia tráfego real para o novo modelo sem retornar suas predições ao usuário, avaliando latência e estabilidade. Deploys Canary liberam uma fração gradual de tráfego (ex: 5%) antes da virada definitiva.",
        questions: [
          q("O que caracteriza a estratégia de deploy em modo Shadow (sombreamento)?", "O novo modelo recebe cópia das requisições reais em paralelo, mas suas predições não são exibidas aos usuários", ["O modelo antigo é deletado permanentemente antes de ligar o novo servidor","O modelo responde apenas para usuários que estão em modo anônimo no navegador"], "Shadow mode testa carga, latência e divergências de predição em ambiente real com risco zero para os clientes."),
          q("Qual é a mecânica de um deploy Canary (canário) em microsserviços de Machine Learning?", "Roteamento progressivo de uma pequena porcentagem do tráfego (ex: 5%) para o novo modelo, expandindo sob validação", ["Execução exclusiva do modelo em máquinas sem conexão com a internet","Troca instantânea de 100% de todo o tráfego do sistema em horário de pico"], "Canary permite detectar anomalias em uma amostra restrita de tráfego antes de atingir toda a base."),
          q("Quais são os gatilhos recomendados para disparar o retreinamento automatizado de um modelo?", "Degradação confirmada em métricas de negócio, detecção de drift severo ou chegada de nova janela de dados", ["Reinicialização forçada do computador do desenvolvedor por atualização do sistema","Alterações estéticas nas cores da interface do usuário do aplicativo"], "Retreinar requer gatilhos baseados em métricas de desempenho, drift populacional ou cronograma justificado."),
          q("Por que o deploy Blue-Green garante reversão instantânea (rollback) em caso de falha grave?", "Porque mantém o ambiente estável anterior (Blue) ligado e pronto enquanto o novo (Green) é validado no roteador", ["Porque ele grava os pesos do modelo em fitas magnéticas imutáveis","Porque dispensa o uso de balanceadores de carga de tráfego de rede"], "Com Blue-Green, o rollback consiste em simplesmente voltar a chave do balanceador para o ambiente estável."),
          t("Qual estratégia de deploy envia tráfego em paralelo para o candidato sem impactar a resposta final ao cliente?", ["shadow","shadow deployment","modo shadow"], "Shadow deployment valida o modelo candidato em ambiente real sem risco operacional."),
          g("Complete o percentual inicial de tráfego direcionado a um modelo candidato em canary:", ["0.05"], "5% (0.05) é uma fatia inicial comum e segura em lançamentos canary.", "peso_trafego_canary = ____  # 5% do tráfego total"),
          o("Ordene as etapas de uma liberação progressiva com Canary deployment:", ["Subir a nova versão candidata do modelo em contêineres dedicados","Direcionar 5% do tráfego do balanceador para a versão candidata","Monitorar taxas de erro HTTP, latência p99 e distribuição de predições","Expandir o tráfego progressivamente até 100% e aposentar a versão legada"], "Deploy paralelo, fração pequena de teste, monitoramento ativo e expansão gradual para 100%."),
          p("Associe a estratégia de deploy à sua principal salvaguarda operacional:", [["Shadow deployment","Validação de estabilidade e latência sem expor respostas aos usuários finais"],["Canary release","Exposição controlada a um subconjunto reduzido de clientes em produção"],["Blue-Green","Reversão instantânea via balanceador de carga em caso de emergência"],["Rollback automatizado","Restauração imediata da versão anterior ao detectar pico de erros ou anomalias"]], "Deploys profissionais de ML priorizam resiliência e continuidade operacional ininterrupta.")
        ]
      }
